-- Fill blank summaries and care for published, exactly identified product codes.
-- Genus/group descriptions deliberately do not assert a species or cultivar.
CREATE TEMP TABLE remaining_plant_care (
 product_code bigint PRIMARY KEY, expected_name text NOT NULL,
 short_text text NOT NULL, care_text text NOT NULL,
 latin text, light text, watering text, guide_light text, guide_water text
) ON COMMIT DROP;
INSERT INTO remaining_plant_care VALUES
 (114,'Кактус Микс','Небольшой кактус из ассортимента; вид и форма растения могут различаться.','Поставьте в светлое место. Обычным пустынным кактусам дайте хорошо дренированный грунт и поливайте после его просыхания; зимой при прохладе полив сокращайте. Если у экземпляра плоские или свисающие побеги, уточните вид: лесным кактусам нужен более мягкий свет и иной режим полива.','Cactaceae',NULL,NULL,'Выберите светлое место; точная потребность в солнце зависит от вида.','Проверяйте просыхание грунта; лесные и пустынные кактусы поливают по-разному.'),
 (115,'Кактус (с цветками)','Цветущий кактус из ассортимента; окраска и вид цветков зависят от экземпляра.','Держите в светлом месте и обеспечьте сток воды из горшка. Поливайте после просыхания грунта, не оставляя воду в поддоне. Вид кактуса не указан: если побеги плоские либо свисающие, проверьте уход для лесных кактусов, которым обычно нужен более мягкий свет.','Cactaceae',NULL,NULL,'Светлое место; прямое солнце вводите постепенно с учётом вида.','После просыхания грунта, без застоя воды; режим зависит от вида кактуса.'),
 (119,'Калатея','Декоративнолистное растение с рисунком на листьях; точный сорт не указан.','Держите в тепле при ярком рассеянном свете без прямого полуденного солнца. В период роста поддерживайте грунт равномерно слегка влажным, но не мокрым; зимой поливайте осторожнее. Берегите от холодных сквозняков и сухого воздуха.',NULL,'diffused','moderate','Яркий рассеянный свет, без палящего солнца.','Во время роста поддерживайте лёгкую влажность грунта без застоя воды; зимой поливайте реже.'),
 (151,'Монстера Медиум Сильвер','Монстера с серебристым оттенком листвы; точный вид по торговому названию не установлен.','Дайте яркий рассеянный свет и рыхлый субстрат с хорошим стоком воды. Поливайте после подсыхания верхнего слоя, не оставляя горшок в воде. Название «Медиум Сильвер» не позволяет надёжно определить вид, поэтому форма взрослых листьев может отличаться.',NULL,'diffused','moderate','Яркий рассеянный свет; защищайте листья от жёсткого прямого солнца.','Поливайте после подсыхания верхнего слоя рыхлого субстрата; слейте лишнюю воду.'),
 (164,'Пальмы микс (Арека и Хамедорея)','Ассортимент комнатных пальм: арека или хамедорея. Конкретный вид выбирается по наличию.','Поставьте в яркий рассеянный свет и берегите от сухого горячего воздуха и холодных сквозняков. Поливайте после лёгкого подсыхания поверхности грунта без застоя воды. Условия для конкретного экземпляра уточняйте после определения вида пальмы.','Arecaceae','diffused','moderate','Яркий рассеянный свет; хамедорея переносит лёгкую полутень.','Поливайте после лёгкого подсыхания поверхности, не оставляя воду в поддоне.'),
 (166,'Пеперомия','Компактная пеперомия с декоративной листвой; форма листьев зависит от вида.','Поставьте в яркий рассеянный свет и защищайте от холодных сквозняков. Дайте верхним нескольким сантиметрам грунта просохнуть между поливами; длительно мокрый субстрат может привести к загниванию корней.',NULL,'diffused','moderate','Яркий рассеянный свет без жёсткого полуденного солнца.','Поливайте после просыхания верхних нескольких сантиметров грунта.'),
 (181,'Соланум (Паслен)','Декоративный паслён; вид и наличие плодов зависят от экземпляра.','Поставьте в светлое место и поливайте после начала подсыхания поверхности грунта, не допуская застоя воды. Вид паслёна не установлен: не употребляйте в пищу его плоды и держите растение вне доступа детей и животных до точного определения.','Solanum','diffused','moderate','Светлое место с мягким солнцем, защищённое от перегрева.','Поддерживайте умеренную влажность грунта, давая поверхности слегка подсохнуть.'),
 (182,'Спатифиллум крашеный','Спатифиллум с декоративной окраской покрывала; внешний вид может измениться после цветения.','Держите в тепле при рассеянном свете. Поливайте умеренно после подсыхания поверхности грунта, не оставляя корни в стоячей воде. Окраска покрывала получена обработкой и не определяет будущий цвет новых соцветий.',NULL,'diffused','moderate','Рассеянный свет без прямого полуденного солнца.','Поливайте после подсыхания поверхности грунта, без застоя воды.'),
 (187,'Суккулент (микс)','Суккулент из ассортимента; форма, окраска и вид зависят от экземпляра.','Выберите светлое место и хорошо дренированный субстрат. Обычно суккуленты поливают после просыхания грунта и не оставляют воду в поддоне; виды с мягкими лесными побегами могут требовать иного режима. Для точного ухода определите вид по этикетке или фото.',NULL,NULL,NULL,'Светлое место; переносимость прямого солнца зависит от вида.','После просыхания грунта; точный режим уточните по виду.'),
 (189,'Тилландсия микс','Тилландсия из ассортимента; размер и форма листьев зависят от вида.','Обеспечьте яркий рассеянный свет и движение воздуха. Смачивайте растение мягкой водой, затем дайте ему полностью просохнуть; не оставляйте воду надолго в розетке. Частоту увлажнения подбирайте по виду и влажности воздуха.',NULL,'diffused','frequent','Яркий рассеянный свет при хорошей циркуляции воздуха.','Увлажняйте мягкой водой и обязательно просушивайте растение после полива.'),
 (192,'Фиалка в ассортименте','Комнатная фиалка из ассортимента; окраска цветков зависит от экземпляра.','Поставьте в светлое место без палящего солнца и холодных сквозняков. Поливайте водой комнатной температуры, когда поверхность субстрата начинает подсыхать; избегайте длительного переувлажнения и попадания холодной воды на листья.','Streptocarpus (Saintpaulia group)','diffused','moderate','Яркий рассеянный свет, без палящего солнца.','Поливайте водой комнатной температуры после подсыхания поверхности грунта.'),
 (193,'Фикус Али','Фикус с длинными узкими листьями и стройным силуэтом.','Поставьте в яркий рассеянный свет и избегайте резких перестановок и холодных сквозняков. Поливайте, когда верхние сантиметры грунта подсохнут; лишнюю воду из поддона сливайте. Точное ботаническое название сорта лучше сверить по этикетке.',NULL,'diffused','moderate','Яркий рассеянный свет; не переставляйте резко в более тёмное место.','Поливайте после подсыхания верхнего слоя грунта, без застоя воды.'),
 (195,'Фикус Амстел','Фикус с узкой удлинённой листвой для светлого интерьера.','Держите при ярком рассеянном свете вдали от холодных сквозняков. Поливайте после подсыхания верхнего слоя грунта; не оставляйте воду в кашпо. Точный сорт линейки «Амстел» без этикетки не утверждаем.',NULL,'diffused','moderate','Яркий рассеянный свет, без резкой смены места.','Поливайте после подсыхания верхнего слоя грунта, слейте лишнюю воду.'),
 (206,'Фикус Майя','Декоративный фикус «Майя»; точный ботанический вид требует сверки по этикетке.','Выберите яркий рассеянный свет и защищайте от холодных сквозняков. Поливайте после подсыхания верхнего слоя грунта, не оставляя воду в поддоне. Не меняйте условия резко: фикусы могут реагировать сбросом листьев.',NULL,'diffused','moderate','Яркий рассеянный свет и стабильное место.','Поливайте после подсыхания верхнего слоя грунта, без застоя воды.'),
 (211,'Фикус Панда','Фикус «Панда» с плотной декоративной кроной; вид уточняется по этикетке.','Поставьте в яркий рассеянный свет. Поливайте после подсыхания верхнего слоя грунта и обеспечьте хороший сток воды. Берегите от холодных сквозняков и резких перестановок.',NULL,'diffused','moderate','Яркий рассеянный свет и стабильное место.','Поливайте после подсыхания верхнего слоя грунта, без застоя воды.'),
 (83,'Бонсай Сосна','Хвойное дерево, сформированное как бонсай; вид сосны не указан.','Держите на открытом воздухе в светлом месте: сосне необходим сезонный цикл, поэтому постоянное содержание в комнате не подходит. Проверяйте влажность небольшого горшка регулярно и поливайте после начала подсыхания субстрата; не допускайте застоя воды. Зимой защищайте корни контейнера от сильного промерзания.','Pinus','sunny','moderate','На открытом воздухе на солнце; не держите постоянно в комнате.','Проверяйте небольшой горшок и поливайте после начала подсыхания субстрата.'),
 (864,'Бонсай Фисташка D15','Фисташковое дерево в форме бонсая; точный вид не указан.','Поставьте в очень светлое место с хорошей вентиляцией и дренированным субстратом. Поливайте после подсыхания поверхности грунта, не оставляя воду в поддоне. Условия зимовки зависят от вида Pistacia и должны быть уточнены по маркировке экземпляра.','Pistacia',NULL,NULL,'Очень светлое место; точный режим зависит от вида фисташки.','После подсыхания поверхности грунта, без застоя воды.');

UPDATE products AS p SET
 latin_name = CASE WHEN BTRIM(COALESCE(p.latin_name,''))='' AND c.latin IS NOT NULL THEN c.latin ELSE p.latin_name END,
 short_description = CASE WHEN BTRIM(COALESCE(p.short_description,''))='' THEN c.short_text ELSE p.short_description END,
 care_instructions = CASE WHEN BTRIM(COALESCE(p.care_instructions,''))='' THEN c.care_text ELSE p.care_instructions END,
 light_level = CASE WHEN BTRIM(COALESCE(p.light_level,''))='' AND c.light IS NOT NULL THEN c.light ELSE p.light_level END,
 watering = CASE WHEN BTRIM(COALESCE(p.watering,''))='' AND c.watering IS NOT NULL THEN c.watering ELSE p.watering END,
 plant_passport = COALESCE(p.plant_passport,'{}'::jsonb)
  || CASE WHEN BTRIM(COALESCE(p.plant_passport->>'lighting',''))='' THEN jsonb_build_object('lighting',c.guide_light) ELSE '{}'::jsonb END
  || CASE WHEN BTRIM(COALESCE(p.plant_passport->>'watering',''))='' THEN jsonb_build_object('watering',c.guide_water) ELSE '{}'::jsonb END,
 updated_at = CURRENT_TIMESTAMP
FROM remaining_plant_care AS c
WHERE p.product_code=c.product_code AND p.catalog_section='plants' AND p.name=c.expected_name
 AND (BTRIM(COALESCE(p.short_description,''))='' OR BTRIM(COALESCE(p.care_instructions,''))=''
  OR (c.latin IS NOT NULL AND BTRIM(COALESCE(p.latin_name,''))='')
  OR (c.light IS NOT NULL AND BTRIM(COALESCE(p.light_level,''))='')
  OR (c.watering IS NOT NULL AND BTRIM(COALESCE(p.watering,''))='')
  OR BTRIM(COALESCE(p.plant_passport->>'lighting',''))='' OR BTRIM(COALESCE(p.plant_passport->>'watering',''))='');
